from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django_celery_beat.models import PeriodicTask
import json

class TaskExecutionConfigDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, task_id):
        try:
            # Enforce that the task name includes the requesting user's organization prefix
            org_prefix = f"org_{request.user.organization_id}_"
            task = PeriodicTask.objects.get(id=task_id, name__startswith=org_prefix)
        except PeriodicTask.DoesNotExist:
            return Response({'error': 'Task not found'}, status=status.HTTP_404_NOT_FOUND)

        return Response({
            'task_id': task.id,
            'name': task.name,
            'task_path': task.task,
            'args': json.loads(task.args or '[]'),
            'kwargs': json.loads(task.kwargs or '{}'),
            'last_run_at': task.last_run_at
        })
